-- Launch copy: remove demonstration wording from stored catalogue and settings.
-- Only text that still matches the original demonstration defaults is replaced; owner edits are kept.
UPDATE products SET data=json_set(data,'$.condition',replace(json_extract(data,'$.condition'),' (demo)','')),revision=revision+1
WHERE json_extract(data,'$.condition') LIKE '% (demo)';
UPDATE store_settings SET data=json_set(data,'$.ordering','Choose your fragrance, enter your delivery details and review the total. Pay by direct UPI or through Razorpay. Your order is confirmed as soon as the payment is verified.'),revision=revision+1 WHERE id=1 AND json_extract(data,'$.ordering')='Choose your fragrance, enter delivery details and review the total. Try the sample UPI flow; orders stay awaiting verification until the owner approves payment.';
UPDATE store_settings SET data=json_set(data,'$.shipping','Delivery charges are shown at checkout before you pay. Once your order ships, its courier and tracking details appear on your private order page.'),revision=revision+1 WHERE id=1 AND json_extract(data,'$.shipping')='Shipping locations, charges and delivery estimates will be confirmed by the seller. Owner-approved shipping information is pending.';
UPDATE store_settings SET data=json_set(data,'$.payment','Pay by direct UPI or through Razorpay, with no added payment fee. Direct UPI orders are confirmed once we verify the payment. For cancellations or returns, contact us with your order reference.'),revision=revision+1 WHERE id=1 AND json_extract(data,'$.payment')='Sample merchant UPI checkout is available for demonstration. No real payment should be made. The owner checks the bank receipt before confirming an order; returns and cancellation terms need owner approval.';
UPDATE store_settings SET data=json_set(data,'$.faq','Are prices and stock up to date?|Yes for anything you can add to your bag; checkout rechecks the price and stock before you pay. Community offers show dated seller quotes, so confirm the current price, availability and terms with us.
What is a decant?|A smaller amount transferred from the original bottle into a separate atomiser. The photo shows the original bottle for reference, not the decant packaging.
Does adding to my bag reserve stock?|No. Your bottles are held once you place an order at checkout, and released if payment is not completed in time.
How do delivery and payment work?|Delivery charges are shown at checkout before you pay. Choose direct UPI or Razorpay; there is no added payment fee.'),revision=revision+1 WHERE id=1 AND json_extract(data,'$.faq')='Are these live prices?|No. Original demo items use sample prices and stock. Community offers show dated seller quotes; confirm current price, availability and terms before buying.
What is a decant?|A smaller amount transferred into a separate atomiser. In this demo, the original bottle photo identifies the fragrance; it does not show the decant packaging.
Does my enquiry reserve stock?|No. Adding to the bag or opening WhatsApp does not reserve stock or confirm an order.
How do shipping and payment work?|The seller will confirm shipping charges, payment details and any applicable policies before you decide.';
